insert into public.tarot_categories (id, label, title, description, sort_order) values
  ('relationship', 'Relationship', 'Percintaan', 'Hubungan romantis: pasangan, gebetan, mantan, komitmen, dan perasaan di antara dua orang.', 1),
  ('friendship', 'Friendship', 'Pertemanan', 'Teman dan sahabat, lingkaran sosial, komunitas, serta dinamika persahabatan.', 2),
  ('career', 'Career', 'Karier', 'Pekerjaan, studi, bisnis, jalur profesional, dan hubungan di tempat kerja atau kampus.', 3),
  ('finance', 'Finance', 'Keuangan', 'Uang, tabungan, utang, pengeluaran, penghasilan, dan rasa aman secara finansial.', 4),
  ('family', 'Family', 'Keluarga', 'Orang tua, saudara, anak, rumah tangga, dan dinamika di dalam keluarga.', 5),
  ('self-discovery', 'Self-discovery', 'Mengenal Diri', 'Jati diri, perasaan terdalam, intuisi, makna hidup, dan hubungan dengan diri sendiri.', 6),
  ('personal-growth', 'Personal Growth', 'Pertumbuhan Diri', 'Kebiasaan, disiplin, penyembuhan, keterampilan, dan proses menjadi versi diri yang lebih baik.', 7),
  ('life-decisions', 'Life Decisions', 'Keputusan Hidup', 'Pilihan penting, persimpangan jalan, waktu yang tepat, dan arah hidup ke depan.', 8)
insert into public.tarot_cards (id, name, card_number, arcana, suit, sort_order, image_path, keywords_upright, keywords_reversed, meaning_upright, meaning_reversed, description, guidance_upright, guidance_reversed, tone_upright, tone_reversed) values
  ('the-fool', 'The Fool', 0, 'major', null, 0, '/cards/the-fool.svg', array['awal baru', 'spontanitas', 'kepolosan', 'lompatan iman', 'kebebasan']::text[], array['ceroboh', 'ragu melangkah', 'naif', 'terlalu impulsif', 'menunda awal']::text[], 'Si Pengelana berdiri di tepi tebing dengan hati ringan: awal yang segar menantimu, dan yang diminta adalah keberanian untuk melangkah sebelum semuanya terlihat pasti. Percayalah pada rasa ingin tahu, tetapi tetap bawa bekal secukupnya.', 'Energi si Pengelana tersendat atau malah kebablasan: kamu bisa terlalu ceroboh dan lupa melihat jurang di depan, atau sebaliknya terlalu takut sehingga awal yang kamu inginkan terus tertunda. Yang dicari adalah titik tengah antara berani dan waspada.', 'Seorang pemuda berpakaian cerah melangkah ke tepi tebing dengan wajah menengadah, memanggul buntalan di ujung tongkat dan menggenggam setangkai mawar putih. Seekor anjing kecil melompat di kakinya, matahari bersinar di belakang, dan pegunungan bersalju membentang jauh — lambang kepolosan, naluri, dan perjalanan yang baru dimulai.', 'Ambil satu langkah kecil yang selama ini kamu tunda, lalu biarkan jalan berikutnya terlihat sambil kamu berjalan.', 'Periksa pijakanmu sebentar sebelum melompat, tetapi jangan biarkan kehati-hatian berubah menjadi alasan untuk tidak pernah berangkat.', 2, -1),
  ('the-magician', 'The Magician', 1, 'major', null, 1, '/cards/the-magician.svg', array['kemauan', 'manifestasi', 'keterampilan', 'inisiatif', 'sumber daya']::text[], array['manipulasi', 'bakat tersia-sia', 'tipu daya', 'kurang fokus', 'janji kosong']::text[], 'Semua alat sudah ada di mejamu: api, air, udara, dan tanah. Yang dibutuhkan hanyalah niat yang jelas dan tindakan yang terarah. Kamu punya kapasitas untuk mengubah gagasan menjadi kenyataan.', 'Kemampuan ada, tetapi arahnya kabur atau dipakai dengan cara yang kurang jujur. Bisa juga bakatmu tersimpan karena ragu, atau perhatianmu terpecah ke terlalu banyak hal sekaligus.', 'Seorang sosok berjubah merah dan putih berdiri di balik meja, satu tangan mengangkat tongkat ke langit dan tangan lainnya menunjuk ke bumi. Di mejanya terdapat cawan, pedang, tongkat, dan koin; di atas kepalanya melayang simbol tak terhingga, sementara mawar dan lili tumbuh di sekelilingnya.', 'Pilih satu niat yang paling penting hari ini, kumpulkan alat yang kamu punya, dan mulai bertindak tanpa menunggu kondisi sempurna.', 'Kembalikan fokus pada satu tujuan dan bersikaplah jujur tentang motifmu; kekuatan tanpa kejernihan mudah berbelok arah.', 2, -1),
  ('the-high-priestess', 'The High Priestess', 2, 'major', null, 2, '/cards/the-high-priestess.svg', array['intuisi', 'rahasia', 'keheningan', 'kebijaksanaan batin', 'misteri']::text[], array['mengabaikan intuisi', 'rahasia tersembunyi', 'kebingungan batin', 'menutup diri', 'permukaan semu']::text[], 'Duduk tenang di antara dua pilar, sang Pendeta mengajak kamu mendengarkan suara yang lebih pelan dari pikiran. Jawaban belum perlu diumumkan; ada hal yang lebih dulu matang dalam diam dan pengamatan.', 'Intuisimu terdengar redup, tertutup keributan pikiran atau keinginan untuk selalu punya jawaban. Ada hal yang belum terungkap, dan terlalu memaksa membuka tirai justru menambah kabut.', 'Seorang perempuan berjubah biru duduk di antara pilar hitam dan putih, mengenakan mahkota bulan dan menggenggam gulungan bertuliskan sebagian kata. Di belakangnya tirai bersulam delima menutup air yang tenang, dan bulan sabit tergeletak di kakinya — lambang pengetahuan tersembunyi dan intuisi.', 'Sediakan jeda hening hari ini dan catat apa yang terasa benar sebelum kamu menjelaskannya dengan kata.', 'Kurangi bising di sekitarmu dan beri ruang bagi perasaan paling pelan; jangan memaksa jawaban sebelum waktunya.', 1, 0),
  ('the-empress', 'The Empress', 3, 'major', null, 3, '/cards/the-empress.svg', array['kesuburan', 'pengasuhan', 'kelimpahan', 'keindahan', 'alam']::text[], array['ketergantungan', 'mengabaikan diri', 'terlalu mengatur', 'kreativitas macet', 'boros']::text[], 'Seperti ladang gandum yang matang, kartu ini membawa kelimpahan, kenyamanan, dan kasih yang menumbuhkan. Kreativitas, tubuh, dan rumah mendapat perhatian; sesuatu yang kamu rawat mulai berbuah.', 'Kasih dan perhatian bisa tersumbat: kamu terlalu memberi hingga lupa diri, atau terlalu mengendalikan hingga orang lain sesak. Kreativitas juga mungkin macet bila kamu menunggu segalanya sempurna.', 'Seorang perempuan duduk di atas kursi berbantal di tengah ladang gandum dengan mahkota dua belas bintang dan jubah bermotif delima. Hutan hijau dan air terjun mengalir di belakangnya, sementara perisai bertanda Venus bersandar di sisinya — lambang bumi yang subur dan kasih yang merawat.', 'Rawat satu hal yang ingin kamu tumbuhkan, entah proyek, hubungan, atau dirimu sendiri, dengan kehangatan yang konsisten.', 'Beri dirimu perhatian yang biasa kamu berikan pada orang lain, dan lepaskan keinginan mengendalikan hasilnya.', 2, -1),
  ('the-emperor', 'The Emperor', 4, 'major', null, 4, '/cards/the-emperor.svg', array['struktur', 'otoritas', 'stabilitas', 'kepemimpinan', 'disiplin']::text[], array['kaku', 'dominasi', 'kontrol berlebihan', 'ego', 'kurang disiplin']::text[], 'Takhta batu sang Kaisar melambangkan fondasi yang dibangun dengan aturan, tanggung jawab, dan keputusan tegas. Struktur bukan kurungan, melainkan kerangka yang membuat hal-hal berharga bisa bertahan.', 'Otoritas bisa menjadi kekakuan, kontrol berlebihan, atau sebaliknya lenyap menjadi kekacauan. Ada pelajaran tentang kepemimpinan: tegas tanpa menindas, teratur tanpa kehilangan kemanusiaan.', 'Seorang pria berjanggut putih duduk di atas takhta batu berhias kepala domba jantan, berbaju zirah di balik jubah merah dengan tongkat ankh dan bola dunia. Pegunungan tandus menjulang di belakangnya dan sungai kecil mengalir — lambang tatanan, kekuasaan, dan tanggung jawab.', 'Susun rencana yang jelas dengan batas dan prioritas, lalu jalankan dengan konsisten.', 'Longgarkan genggaman pada hal yang tidak bisa kamu atur, dan bangun kembali disiplin lewat satu aturan sederhana.', 1, -1),
  ('the-hierophant', 'The Hierophant', 5, 'major', null, 5, '/cards/the-hierophant.svg', array['tradisi', 'bimbingan', 'nilai bersama', 'pendidikan', 'komunitas']::text[], array['dogma', 'memberontak', 'konformitas', 'jalan sendiri', 'kritik terhadap aturan']::text[], 'Sang Hierofan mewakili kebijaksanaan yang diwariskan: guru, tradisi, dan nilai yang telah teruji waktu. Belajar dari struktur yang ada dapat menuntunmu, selama kamu memahami maknanya dan bukan sekadar mengikuti.', 'Aturan lama terasa menyesakkan, atau kamu terlalu bergantung pada otoritas. Ini saat menimbang tradisi mana yang masih bermakna, dan membangun keyakinan yang benar-benar milikmu.', 'Seorang pemuka berjubah merah duduk di antara dua pilar, memakai mahkota bertingkat tiga dan mengangkat tangan memberkati. Dua murid berlutut di depannya, dengan kunci bersilang di kaki — lambang pengetahuan yang diteruskan dari generasi ke generasi.', 'Cari guru, panduan, atau tradisi yang terbukti dan pelajari dengan rendah hati sebelum memodifikasinya.', 'Pertanyakan aturan yang kamu ikuti hanya karena kebiasaan, dan pilih nilai yang sungguh kamu yakini.', 1, 0),
  ('the-lovers', 'The Lovers', 6, 'major', null, 6, '/cards/the-lovers.svg', array['cinta', 'pilihan sadar', 'keselarasan', 'nilai pribadi', 'kemitraan']::text[], array['ketidakselarasan', 'pilihan sulit', 'komunikasi buruk', 'godaan', 'ketidakseimbangan']::text[], 'Dua sosok berdiri telanjang dan jujur di bawah malaikat: kartu ini tentang kedekatan yang tulus dan pilihan yang selaras dengan nilai terdalam. Keputusan sejati dibuat dengan hati dan kesadaran sekaligus.', 'Ada ketidakselarasan antara apa yang kamu katakan dan lakukan, atau dua pihak tidak berada di halaman yang sama. Pilihan yang ditunda atau dibuat dari godaan sesaat perlu ditinjau dari nilai yang kamu pegang.', 'Seorang pria dan seorang perempuan berdiri tanpa busana di taman, di bawah malaikat bersayap yang memberkati dari matahari. Pohon berbuah ular ada di belakang perempuan, pohon berapi di belakang pria, dan gunung menjulang di antara mereka — lambang cinta, pilihan, dan kejujuran.', 'Pilih sesuai nilai yang paling kamu hargai, dan ungkapkan dengan jujur kepada orang yang terlibat.', 'Sebelum memutuskan, tanyakan apakah pilihan ini selaras dengan siapa kamu, bukan hanya apa yang kamu inginkan sekarang.', 2, -1),
  ('the-chariot', 'The Chariot', 7, 'major', null, 7, '/cards/the-chariot.svg', array['tekad', 'kemenangan', 'kendali', 'arah', 'ketangguhan']::text[], array['kehilangan arah', 'agresi', 'kendali lepas', 'terhambat', 'dorongan bertabrakan']::text[], 'Dua sphinx yang berbeda warna ditarik ke satu arah oleh kemauan sang kusir. Dengan tekad dan fokus kamu bisa menyatukan dorongan yang bertentangan dan melaju menuju tujuan.', 'Kemudi terasa lepas: dorongan-dorongan dalam dirimu saling menarik, atau kamu terlalu ngotot sehingga menabrak sekitar. Tentukan arah yang jelas sebelum menambah kecepatan.', 'Seorang kesatria berhelm bintang berdiri di atas kereta tanpa tali kekang di depan tembok kota dan sungai. Dua sphinx, hitam dan putih, berbaring di depan kereta yang berhias bulan sabit di pundaknya — lambang kemauan yang menyatukan kekuatan berlawanan.', 'Tetapkan satu tujuan, satukan energimu ke sana, dan jaga ritme dengan disiplin yang tenang.', 'Hentikan sejenak, rapikan dorongan yang saling bertentangan, lalu pilih arah sebelum melaju lagi.', 2, -1),
  ('strength', 'Strength', 8, 'major', null, 8, '/cards/strength.svg', array['keberanian lembut', 'kesabaran', 'welas asih', 'ketahanan', 'pengendalian diri']::text[], array['keraguan diri', 'kekuatan terkuras', 'emosi tak terkendali', 'rendah diri', 'memaksa']::text[], 'Seorang perempuan menutup rahang singa dengan lembut: kekuatan sejati bukan paksaan, melainkan kesabaran dan kasih yang mantap. Naluri liar dijinakkan lewat pemahaman, bukan perlawanan.', 'Rasa percaya diri tersendat atau emosi terasa lebih kuat dari kendali. Jangan membandingkan dirimu dengan gambaran kuat yang kaku; keberanian bisa berbentuk istirahat dan meminta dukungan.', 'Seorang perempuan berbaju putih dengan simbol tak terhingga di atas kepalanya membelai dan menutup mulut seekor singa dengan lembut. Karangan bunga melingkar di pinggangnya dan pegunungan kuning terbentang di belakang — lambang kekuatan batin yang tenang.', 'Hadapi situasi yang sulit dengan kesabaran dan kelembutan yang tegas, bukan dengan paksaan.', 'Beri dirimu belas kasih, dan ingat bahwa meminta bantuan juga merupakan bentuk keberanian.', 2, -1),
  ('the-hermit', 'The Hermit', 9, 'major', null, 9, '/cards/the-hermit.svg', array['introspeksi', 'kesendirian', 'bimbingan batin', 'pencarian', 'kebijaksanaan']::text[], array['isolasi', 'kesepian', 'menarik diri', 'menolak nasihat', 'tersesat']::text[], 'Sosok berjubah dengan lentera berdiri di puncak sunyi: ini waktu menepi dari kebisingan untuk mencari terang di dalam. Kesendirian di sini bukan kehilangan, melainkan ruang untuk pemahaman.', 'Menyendiri berubah menjadi menarik diri berlebihan atau kesepian yang tidak diinginkan. Mungkin kamu menolak masukan, atau terlalu lama bersembunyi dari dunia.', 'Seorang lelaki tua berjubah abu-abu berdiri di puncak gunung bersalju, memegang tongkat dan lentera berbintang enam titik. Langit sunyi dan hamparan salju sepi menyelubunginya — lambang pencarian, kearifan, dan terang yang dibawa sendiri.', 'Sediakan waktu menyendiri untuk merenung dan menjernihkan apa yang benar-benar penting bagimu.', 'Keluarlah dari persembunyian secara perlahan dan hubungi satu orang tepercaya sebagai pegangan.', 1, -1),
  ('wheel-of-fortune', 'Wheel of Fortune', 10, 'major', null, 10, '/cards/wheel-of-fortune.svg', array['siklus', 'perubahan nasib', 'titik balik', 'peluang', 'takdir']::text[], array['kemunduran', 'melawan perubahan', 'siklus berulang', 'nasib buruk', 'kehilangan kendali']::text[], 'Roda besar terus berputar: yang di bawah naik, yang di atas turun. Perubahan di luar kendalimu sedang bergerak, dan kamu diajak menyesuaikan diri serta memanfaatkan momentum yang datang.', 'Putaran terasa melawanmu, atau kamu mengulang pola lama. Alih-alih meratapi keberuntungan, cari bagian yang masih bisa kamu pengaruhi dan belajar dari siklusnya.', 'Roda besar bertuliskan huruf dan simbol berputar di langit, dikelilingi empat makhluk bersayap yang membaca buku di sudut awan. Ular turun di satu sisi, Anubis naik di sisi lain, dan sphinx duduk di puncak — lambang siklus, takdir, dan perubahan.', 'Terima bahwa situasi berputar, dan gerakkan hal yang ada dalam kuasamu selagi momentum mendukung.', 'Alih-alih menyalahkan nasib, amati pola yang berulang dan ubah satu kebiasaan kecil di dalamnya.', 1, -1),
  ('justice', 'Justice', 11, 'major', null, 11, '/cards/justice.svg', array['keadilan', 'kejujuran', 'sebab-akibat', 'keseimbangan', 'tanggung jawab']::text[], array['ketidakadilan', 'menghindari tanggung jawab', 'bias', 'timbangan miring', 'tidak jujur']::text[], 'Timbangan dan pedang sang Hakim mengingatkan bahwa tindakan membawa konsekuensi. Kejujuran dan penilaian yang adil, terutama terhadap diri sendiri, membantu menyelesaikan persoalan dengan bersih.', 'Ada rasa tidak adil, bias, atau pihak yang lari dari tanggung jawab. Bisa juga kamu menghakimi terlalu keras tanpa melihat gambaran utuh. Kumpulkan fakta sebelum menyimpulkan.', 'Seorang sosok bermahkota duduk tegak di antara dua pilar dengan tirai ungu di belakangnya, tangan kanan mengangkat pedang dan tangan kiri memegang timbangan. Jubah merahnya berpadu pita hijau; tatapannya lurus ke depan — lambang kebenaran, keseimbangan, dan konsekuensi.', 'Lihat keadaan dengan jujur dan lengkap, lalu ambil keputusan yang bisa kamu pertanggungjawabkan.', 'Periksa fakta dan niatmu sendiri sebelum menyalahkan; adil pada diri sendiri adalah awal.', 1, -1),
  ('the-hanged-man', 'The Hanged Man', 12, 'major', null, 12, '/cards/the-hanged-man.svg', array['menyerah', 'sudut pandang baru', 'jeda', 'pengorbanan', 'pelepasan']::text[], array['penundaan sia-sia', 'menolak melepas', 'pengorbanan tanpa arti', 'stagnasi', 'enggan bergerak']::text[], 'Tergantung terbalik dengan tenang, sang Tergantung melihat dunia dari sisi lain. Kadang kemajuan dimulai dengan berhenti, melepas kendali, dan membiarkan pemahaman baru datang.', 'Jeda berubah menjadi macet: kamu menunda tanpa tujuan, mengorbankan diri tanpa imbalan makna, atau menolak melepas hal yang jelas sudah selesai.', 'Seorang pemuda tergantung terbalik dari pohon berbentuk T dengan satu kaki terikat dan kaki lain menekuk. Kedua tangannya di belakang punggung, wajahnya tenang dikelilingi lingkaran cahaya — lambang pelepasan dan sudut pandang baru.', 'Berhenti sebentar dan lihat keadaanmu dari sudut yang berbeda sebelum bertindak lagi.', 'Putuskan apakah penantian ini masih bermakna; jika tidak, lepaskan dan arahkan energimu ke tempat lain.', 0, -1),
  ('death', 'Death', 13, 'major', null, 13, '/cards/death.svg', array['akhir dan awal', 'transformasi', 'pelepasan', 'peralihan', 'pembaruan']::text[], array['menolak perubahan', 'terjebak masa lalu', 'transisi tertahan', 'takut melepas', 'stagnasi']::text[], 'Kartu ini jarang tentang kematian harfiah; ia menandai berakhirnya satu bab agar yang baru bisa tumbuh. Melepas yang sudah selesai terasa berat, tetapi memberi tempat bagi pembaruan.', 'Kamu berpegang pada sesuatu yang sudah usang, atau perubahan terasa tersendat di tengah jalan. Menolak akhir hanya memperpanjang masa peralihan.', 'Rangka berbaju zirah hitam menunggang kuda putih sambil membawa bendera bermotif mawar putih. Seorang raja terjatuh di tanah, pemuka dan perempuan berlutut, sedangkan matahari terbit di antara dua menara — lambang akhir yang membuka awal baru.', 'Akui apa yang sudah selesai, ucapkan terima kasih padanya, lalu lepaskan dengan tenang.', 'Tanyakan apa yang kamu takutkan dari melepas, dan ambil satu langkah kecil menuju bab berikutnya.', -1, -1),
  ('temperance', 'Temperance', 14, 'major', null, 14, '/cards/temperance.svg', array['keseimbangan', 'moderasi', 'kesabaran', 'penyembuhan', 'harmoni']::text[], array['ketidakseimbangan', 'berlebihan', 'tergesa', 'tidak selaras', 'kurang sabar']::text[], 'Malaikat menuang air antara dua cawan dalam aliran lembut: ini tentang mencampur, menakar, dan bersabar. Penyembuhan dan keselarasan datang dari langkah kecil yang konsisten.', 'Ada yang berlebihan atau kurang, entah kerja, emosi, atau kebiasaan. Ketidakselarasan ini bisa diperbaiki dengan menakar ulang dan bersabar pada prosesnya.', 'Seorang malaikat bersayap berdiri dengan satu kaki di air dan satu di darat, menuang cairan dari satu cawan ke cawan lain. Jalan menuju gunung jauh dengan mahkota bersinar, dan bunga iris tumbuh di tepi air — lambang keseimbangan dan penyembuhan.', 'Takar ulang porsi kerja, istirahat, dan perasaanmu; cari campuran yang membuatmu tetap tenang.', 'Hindari ekstrem, dan ambil langkah kecil yang konsisten untuk memulihkan keseimbangan.', 1, -1),
  ('the-devil', 'The Devil', 15, 'major', null, 15, '/cards/the-devil.svg', array['keterikatan', 'godaan', 'ketergantungan', 'bayangan diri', 'materialisme']::text[], array['pembebasan', 'melepas rantai', 'menyadari kebiasaan', 'memutus pola', 'pemulihan']::text[], 'Rantai di leher dua sosok tampak kuat padahal longgar: kartu ini menunjuk keterikatan yang dipilih tanpa sadar, entah pada kebiasaan, hubungan, atau rasa takut. Mengakuinya adalah awal kebebasan.', 'Kamu mulai menyadari rantai yang selama ini menahanmu dan mencari jalan keluar. Proses melepas bisa bertahap dan membutuhkan dukungan, tetapi arahnya menuju pemulihan.', 'Sosok bertanduk berkaki cakar duduk di atas altar hitam sambil mengangkat obor dan tangan memberkati terbalik. Seorang pria dan perempuan telanjang berekor menanggung rantai longgar di leher mereka, di bawah bayangan malam — lambang keterikatan.', 'Tanyakan apa yang mengikatmu dan perhatikan bahwa kamu punya andil untuk melonggarkannya.', 'Pertahankan langkah pembebasanmu dengan dukungan orang tepercaya; kemajuan kecil pun berharga.', -1, 1),
  ('the-tower', 'The Tower', 16, 'major', null, 16, '/cards/the-tower.svg', array['kejutan', 'keruntuhan', 'pencerahan mendadak', 'pembongkaran', 'kebenaran terungkap']::text[], array['menghindari bencana', 'dampak yang tertunda', 'takut perubahan', 'goncangan batin', 'pemulihan']::text[], 'Petir menyambar menara yang dibangun di atas fondasi rapuh: sesuatu runtuh agar kebenaran terlihat. Guncangan terasa keras, namun yang runtuh hanyalah yang memang tidak kokoh.', 'Kamu mungkin menghindari keruntuhan yang sudah terasa dekat, atau sedang memulihkan diri dari guncangan. Menahan perubahan hanya menunda, sementara menata ulang bisa dimulai dari reruntuhan.', 'Sebuah menara tinggi di puncak karang disambar petir yang menjatuhkan mahkotanya, dengan api menyembur dari jendela. Dua sosok jatuh dari menara dalam gelap malam yang dihujani bara — lambang keruntuhan struktur yang rapuh.', 'Utamakan keselamatan dan ketenangan; kemudian periksa fondasi mana yang perlu dibangun lebih kokoh.', 'Hadapi apa yang sudah kamu curigai rapuh, lalu mulai membenahi sedikit demi sedikit.', -2, -1),
  ('the-star', 'The Star', 17, 'major', null, 17, '/cards/the-star.svg', array['harapan', 'pembaruan', 'ketenangan', 'inspirasi', 'penyembuhan']::text[], array['putus asa', 'kehilangan keyakinan', 'terputus', 'pesimis', 'lelah berharap']::text[], 'Setelah badai, bintang-bintang muncul. Kartu ini membawa napas lega: harapan, pemulihan, dan kepercayaan bahwa kamu sedang diarahkan ke tempat yang lebih lapang.', 'Harapan terasa tipis, atau kamu kehilangan keyakinan pada diri dan masa depan. Cahaya tetap ada, hanya perlu perawatan lembut dan dukungan agar terlihat lagi.', 'Seorang perempuan telanjang berlutut di tepi kolam, menuang air dari dua kendi ke tanah dan ke air. Di atasnya sebuah bintang besar bersinar bersama tujuh bintang kecil, dan seekor burung hinggap di pohon — lambang harapan dan penyembuhan.', 'Rawat harapanmu dengan kegiatan sederhana yang menenangkan, dan percayalah pada proses pemulihan.', 'Cari satu sumber penghiburan, orang atau kebiasaan, yang mengingatkanmu bahwa cahaya belum padam.', 2, 0),
  ('the-moon', 'The Moon', 18, 'major', null, 18, '/cards/the-moon.svg', array['ilusi', 'ketidakpastian', 'alam bawah sadar', 'ketakutan', 'mimpi']::text[], array['kejelasan muncul', 'melepas ketakutan', 'kebenaran terungkap', 'kebingungan mereda', 'kecemasan']::text[], 'Cahaya bulan membuat bayangan tampak berubah-ubah: batas antara nyata dan khayal kabur. Perasaan, mimpi, dan kecemasan menguat, jadi berjalanlah pelan dan jangan menarik kesimpulan dari bayang-bayang.', 'Kabut mulai terangkat dan kebenaran lebih jelas, atau kecemasan yang terpendam muncul ke permukaan. Ini kesempatan memilah antara ketakutan dan fakta.', 'Bulan purnama dengan wajah bersinar menggantung di antara dua menara, meneteskan titik cahaya. Seekor anjing dan serigala melolong di sisi jalan, sementara kepiting merangkak keluar dari kolam menuju jalur yang menuju pegunungan — lambang naluri dan ketidakpastian.', 'Pelan-pelan saja; tunda keputusan besar sampai gambarannya lebih jelas dan tulis kecemasanmu untuk dipilah.', 'Pisahkan fakta dari asumsi, dan beri nama pada ketakutan yang mulai terlihat agar mereda.', -1, 0),
  ('the-sun', 'The Sun', 19, 'major', null, 19, '/cards/the-sun.svg', array['kegembiraan', 'keberhasilan', 'vitalitas', 'kejelasan', 'optimisme']::text[], array['kegembiraan teredam', 'optimisme berlebihan', 'penundaan sukses', 'energi rendah', 'kurang percaya diri']::text[], 'Matahari bersinar penuh di atas anak yang tertawa: ini kartu terang, hangat, dan terbuka. Kejelasan, keberhasilan, dan sukacita sederhana datang, dan kamu dipersilakan menikmatinya tanpa rasa bersalah.', 'Kegembiraanmu tertutup awan tipis: energi rendah, atau optimisme yang terlalu besar mengabaikan detail. Cahaya tetap ada, hanya butuh kejujuran dan waktu agar terasa kembali.', 'Matahari besar berwajah bersinar di langit kuning di atas tembok bata. Seorang anak telanjang menunggang kuda putih sambil memegang bendera merah, dikelilingi bunga matahari — lambang kegembiraan, kemurnian, dan vitalitas.', 'Rayakan hal baik yang sudah terjadi dan bagikan kehangatan itu kepada orang di sekitarmu.', 'Hangatkan dirimu pelan-pelan lewat hal sederhana yang menyenangkan, dan jangan memaksa antusiasme.', 2, 1),
  ('judgement', 'Judgement', 20, 'major', null, 20, '/cards/judgement.svg', array['panggilan', 'pembaruan diri', 'refleksi', 'pengampunan', 'kebangkitan']::text[], array['keraguan diri', 'menolak panggilan', 'kritik diri', 'penyesalan', 'menunda evaluasi']::text[], 'Terompet berbunyi dan orang-orang bangkit dari peti: waktunya menilai perjalananmu dengan jujur, memaafkan, dan menjawab panggilan yang lebih besar. Kamu diajak melangkah sebagai dirimu yang telah belajar.', 'Kamu menolak mendengar panggilan batin, atau terlalu keras menghakimi diri atas masa lalu. Refleksi yang adil, bukan kejam, diperlukan agar bisa melangkah.', 'Seorang malaikat meniup terompet dari awan dengan bendera bersalib, sementara orang-orang telanjang bangkit dari peti dengan tangan terangkat. Gunung dan laut membentang di belakang mereka — lambang kebangkitan dan evaluasi.', 'Tinjau perjalananmu dengan jujur, maafkan yang perlu dimaafkan, dan jawab panggilan yang terus kamu rasakan.', 'Berhenti mengadili diri secara berlebihan; belajar dari masa lalu lalu pilih satu langkah baru.', 1, -1),
  ('the-world', 'The World', 21, 'major', null, 21, '/cards/the-world.svg', array['penyelesaian', 'pencapaian', 'keutuhan', 'integrasi', 'perayaan']::text[], array['hampir selesai', 'penutupan tertunda', 'kurang tuntas', 'menunda akhir', 'stagnan']::text[], 'Penari di tengah karangan bunga menandai satu siklus yang selesai dengan utuh. Kamu telah menempuh perjalanan panjang, dan inilah saat menikmati pencapaian sebelum memulai bab berikutnya.', 'Bagian akhir terasa belum tuntas: ada urusan yang menggantung, atau kamu enggan menutup karena takut kehilangan rasa tujuan. Selesaikan yang tersisa agar bisa benar-benar melangkah.', 'Seorang penari berselendang berdiri di tengah karangan laurel berbentuk oval, memegang dua tongkat. Di empat sudut kartu tampak manusia, elang, singa, dan banteng bersayap — lambang keutuhan dan penyelesaian.', 'Akui capaianmu, rayakan dengan tulus, dan bersiaplah menyambut siklus berikutnya.', 'Identifikasi satu hal yang belum tuntas dan selesaikan, agar kamu bisa menutup bab ini dengan lega.', 2, 0),
  ('ace-of-wands', 'Ace of Wands', 1, 'minor', 'wands', 22, '/cards/ace-of-wands.svg', array['percikan ide', 'semangat baru', 'potensi', 'inspirasi', 'dorongan']::text[], array['semangat padam', 'ide tertunda', 'ragu memulai', 'energi tersendat', 'awal yang goyah']::text[], 'Sebuah tangan dari awan menyodorkan tongkat yang bertunas: percikan inspirasi dan energi baru siap menyala. Peluang untuk memulai sesuatu yang kamu antusiasi sedang terbuka lebar.', 'Percikan ide ada, tetapi sulit menyala: ragu, lelah, atau waktu yang belum pas membuat langkah pertama tertunda. Jaga apinya kecil dulu agar tidak padam.', 'Sebuah tangan muncul dari awan menggenggam tongkat kayu yang menumbuhkan daun-daun muda yang berguguran. Di bawahnya terbentang lembah hijau dengan sungai, pohon, dan kastil di atas bukit jauh — lambang awal yang penuh tenaga.', 'Tuliskan satu ide yang membuatmu bersemangat dan lakukan langkah pertamanya hari ini.', 'Lindungi percikan kecilmu: pilih satu ide, beri waktu singkat setiap hari, dan abaikan tuntutan hasil cepat.', 2, -1),
  ('two-of-wands', 'Two of Wands', 2, 'minor', 'wands', 23, '/cards/two-of-wands.svg', array['perencanaan', 'pilihan masa depan', 'visi', 'keputusan awal', 'cakrawala']::text[], array['takut keluar zona nyaman', 'rencana buruk', 'ragu', 'tanpa arah', 'menunda']::text[], 'Sang pengamat menggenggam bola dunia di atas benteng, menimbang langkah berikutnya. Kamu sudah memiliki sesuatu; kini saatnya memetakan ke mana akan melangkah dan memilih arah yang lebih luas.', 'Rencana terasa mengambang atau rasa takut meninggalkan zona nyaman membuatmu berdiam. Tanpa keputusan, cakrawala hanya menjadi pemandangan.', 'Seorang sosok berjubah berdiri di atas benteng sambil memegang bola dunia kecil di satu tangan dan tongkat di tangan lain, dengan tongkat kedua tertancap di dinding. Laut dan pelabuhan membentang di kejauhan di bawah langit kuning — lambang perencanaan dan pilihan.', 'Tuliskan dua atau tiga arah yang mungkin, lalu pilih satu untuk diuji dalam skala kecil.', 'Pertanyakan apa yang kamu takutkan dari melangkah, dan tentukan batas waktu untuk memutuskan.', 1, -1),
  ('three-of-wands', 'Three of Wands', 3, 'minor', 'wands', 24, '/cards/three-of-wands.svg', array['perluasan', 'menanti hasil', 'visi jauh', 'kemajuan', 'peluang luar']::text[], array['hambatan', 'penundaan', 'rencana tersendat', 'kurang persiapan', 'kecewa menunggu']::text[], 'Sosok di tebing memandang kapal-kapalnya berlayar: rencana sudah bergerak dan kini saatnya menunggu hasil sambil melihat ke cakrawala lebih luas. Peluang di luar lingkunganmu mulai terbuka.', 'Rencana tersendat oleh penundaan atau persiapan yang kurang. Harapan akan hasil cepat berhadapan dengan realitas yang menuntut kesabaran.', 'Seorang sosok berjubah membelakangi kita di puncak tebing, bertumpu pada tongkat sambil memandang laut dengan kapal berlayar. Dua tongkat lain tertancap di sisinya, dan matahari kuning berada di cakrawala — lambang visi dan ekspansi.', 'Lanjutkan langkahmu dengan sabar dan perluas pandangan ke peluang yang lebih jauh.', 'Periksa bagian rencana yang belum siap, perbaiki, lalu lanjutkan; penundaan bisa jadi kesempatan menyempurnakan.', 1, -1),
  ('four-of-wands', 'Four of Wands', 4, 'minor', 'wands', 25, '/cards/four-of-wands.svg', array['perayaan', 'rumah', 'harmoni', 'kebersamaan', 'tonggak']::text[], array['ketegangan rumah', 'perayaan tertunda', 'kurang rasa memiliki', 'transisi', 'ketidakstabilan']::text[], 'Empat tongkat berhias bunga membentuk gerbang perayaan. Ini tentang tonggak yang dirayakan bersama, rumah yang hangat, dan rasa aman dalam kebersamaan.', 'Suasana perayaan terasa kurang pas: ada ketegangan di rumah, rencana pesta tertunda, atau kamu merasa belum benar-benar diterima. Beri ruang untuk membangun rasa memiliki.', 'Empat tongkat tinggi berhias karangan bunga dan pita membentuk kanopi, dengan dua sosok mengangkat buket di depannya. Kastil dan orang-orang yang menari terlihat di kejauhan di bawah langit cerah — lambang perayaan dan kebersamaan.', 'Rayakan satu pencapaian, sekecil apa pun, bersama orang yang berarti bagimu.', 'Mulailah dari hal sederhana untuk membuat rumah atau lingkunganmu terasa hangat dan aman.', 2, 0),
  ('five-of-wands', 'Five of Wands', 5, 'minor', 'wands', 26, '/cards/five-of-wands.svg', array['persaingan', 'konflik kecil', 'perbedaan pendapat', 'adu ide', 'ketegangan']::text[], array['menghindari konflik', 'perselisihan reda', 'kompromi', 'ketegangan tersembunyi', 'kelelahan']::text[], 'Lima orang mengayunkan tongkat tanpa saling mengenai: riuh, kacau, dan penuh tenaga. Ini tentang persaingan atau perbedaan pendapat yang bisa menajamkan, selama tidak berubah jadi perkelahian.', 'Perselisihan mereda, atau justru dipendam dan menjadi ketegangan tersembunyi. Mencari titik temu lebih menguntungkan daripada menang sendiri.', 'Lima pemuda berpakaian berbeda warna mengayunkan tongkat kayu satu sama lain di atas tanah lapang, dengan langit biru cerah di atas mereka. Tak ada yang terluka; semuanya tampak seperti latihan tanding yang berisik — lambang konflik dan persaingan.', 'Salurkan perbedaan pendapat menjadi diskusi yang sehat, dan pilih pertarungan yang benar-benar penting.', 'Cari titik temu dan sampaikan kebutuhanmu dengan tenang daripada menahan emosi sampai meledak.', -1, 0),
  ('six-of-wands', 'Six of Wands', 6, 'minor', 'wands', 27, '/cards/six-of-wands.svg', array['kemenangan', 'pengakuan', 'percaya diri', 'pencapaian', 'apresiasi']::text[], array['kurang pengakuan', 'ego', 'kegagalan publik', 'jatuh', 'rasa tidak layak']::text[], 'Penunggang kuda berkalung laurel disambut sorak-sorai. Usahamu mendapat pengakuan, dan keberhasilan ini layak dinikmati dengan rendah hati.', 'Pengakuan yang kamu harapkan tertunda atau bahkan diraih orang lain. Bisa juga kebanggaan berubah menjadi ego yang rapuh. Nilai dirimu tidak bergantung pada tepuk tangan.', 'Seorang penunggang menunggang kuda putih berhias kain hijau, mengenakan mahkota laurel dan memegang tongkat berkalung laurel. Orang-orang berjalan di sisinya mengangkat tongkat mereka di bawah langit biru — lambang kemenangan dan pengakuan.', 'Terima pujian dengan lapang dan bagikan kredit pada orang yang membantumu.', 'Ingatkan dirimu bahwa nilai diri tidak ditentukan oleh sorak, dan lanjutkan dengan standar milikmu.', 2, -1),
  ('seven-of-wands', 'Seven of Wands', 7, 'minor', 'wands', 28, '/cards/seven-of-wands.svg', array['mempertahankan', 'keteguhan', 'tantangan', 'keberanian', 'batas']::text[], array['kewalahan', 'menyerah', 'terlalu defensif', 'kelelahan', 'kompromi']::text[], 'Berdiri di atas bukit, sosok ini mempertahankan posisinya dari banyak tongkat yang mengarah ke bawah. Kamu sedang diuji, dan keteguhan serta batas yang jelas membantu menjaga apa yang sudah kamu bangun.', 'Terlalu banyak serangan atau tuntutan membuatmu lelah dan ingin menyerah. Kadang mundur sejenak atau meminta bantuan lebih bijak daripada bertahan sendirian.', 'Seorang pria berdiri di puncak bukit menggenggam tongkat, sementara enam tongkat lain mencuat dari bawah ke arahnya. Dia mengenakan sepatu yang tidak serasi dan menatap ke bawah dengan waspada — lambang mempertahankan pendirian.', 'Pertahankan batasmu dengan tenang, dan tentukan apa yang benar-benar layak kamu bela.', 'Kurangi pertempuran yang tidak perlu dan cari dukungan; kamu tidak harus menghadapi semuanya sendiri.', 0, -1),
  ('eight-of-wands', 'Eight of Wands', 8, 'minor', 'wands', 29, '/cards/eight-of-wands.svg', array['kecepatan', 'kemajuan cepat', 'kabar', 'momentum', 'aksi']::text[], array['penundaan', 'terburu-buru', 'kekacauan', 'miskomunikasi', 'momentum hilang']::text[], 'Delapan tongkat melesat di udara menuju sasaran. Hal-hal bergerak cepat: kabar datang, rencana melaju, dan momentum bisa dimanfaatkan sebelum hilang.', 'Kecepatan berubah menjadi kekacauan atau justru semuanya tertahan. Pesan salah sampai, jadwal berantakan, atau energi terbuang karena terburu-buru.', 'Delapan tongkat melayang sejajar menuju kanan di atas lanskap sungai dan bukit hijau, dengan langit biru cerah. Tak ada sosok manusia, hanya gerakan yang meluncur ke sasaran — lambang kecepatan dan kemajuan.', 'Manfaatkan momentum sekarang: kirim pesan, ambil keputusan, dan gerakkan rencana yang sudah siap.', 'Perlambat sejenak, pastikan arah dan komunikasimu jelas, lalu lanjutkan dengan ritme yang bisa dijaga.', 1, -1),
  ('nine-of-wands', 'Nine of Wands', 9, 'minor', 'wands', 30, '/cards/nine-of-wands.svg', array['ketahanan', 'kewaspadaan', 'hampir sampai', 'luka lama', 'bertahan']::text[], array['kelelahan', 'paranoia', 'menyerah', 'terlalu defensif', 'beban berat']::text[], 'Dengan perban di kepala dan tongkat sebagai sandaran, sosok ini hampir mencapai garis akhir. Pengalaman pahit membuatmu waspada, tetapi ketahananmu sudah membuktikan diri. Bertahanlah sedikit lagi.', 'Kelelahan memuncak dan kewaspadaan berubah menjadi curiga berlebihan. Kamu mungkin ingin menyerah di ujung jalan; istirahat dan bantuan dibutuhkan, bukan dinding yang lebih tinggi.', 'Seorang pria berkepala berperban bersandar pada satu tongkat sambil menatap waspada ke samping. Delapan tongkat berdiri seperti pagar di belakangnya di bawah langit pucat — lambang ketahanan dan kewaspadaan setelah banyak pertempuran.', 'Ambil napas, kumpulkan sisa tenagamu, dan selesaikan langkah terakhir dengan hati-hati.', 'Izinkan dirimu beristirahat dan menerima bantuan; tidak semua ancaman membutuhkan penjagaan penuh.', 0, -1),
  ('ten-of-wands', 'Ten of Wands', 10, 'minor', 'wands', 31, '/cards/ten-of-wands.svg', array['beban', 'tanggung jawab', 'kerja keras', 'terbebani', 'hampir tuntas']::text[], array['melepas beban', 'delegasi', 'kewalahan', 'burnout', 'menyerah']::text[], 'Sosok membungkuk menggendong sepuluh tongkat menuju desa. Kamu memikul banyak tanggung jawab, sebagian karena pilihanmu sendiri. Tujuan sudah terlihat, tetapi beban perlu dipikirkan ulang.', 'Beban terasa terlalu berat, atau kamu mulai melepasnya dengan membagi tugas. Kamu tidak harus memikul semuanya sendirian.', 'Seorang pria membungkuk menggendong seikat sepuluh tongkat besar di punggungnya, wajahnya tertutup tongkat. Dia berjalan menuju rumah-rumah di ujung jalan di bawah langit jingga — lambang tanggung jawab dan beban berat.', 'Tinjau apa yang kamu pikul dan tentukan mana yang bisa dibagi, ditunda, atau dilepas.', 'Teruskan pendelegasian dan beri dirimu ijin untuk berkata tidak pada tambahan beban.', -1, 0),
  ('page-of-wands', 'Page of Wands', 11, 'minor', 'wands', 32, '/cards/page-of-wands.svg', array['rasa ingin tahu', 'kabar menggembirakan', 'semangat pemula', 'eksplorasi', 'kreativitas muda']::text[], array['kurang fokus', 'ide tak terwujud', 'impulsif', 'kabar tertunda', 'cepat bosan']::text[], 'Seorang pembawa pesan muda berdiri dengan tongkat di padang pasir, penuh antusias dan rasa ingin tahu. Sosok atau sikap ini membawa kabar baru, ide segar, dan keberanian mencoba.', 'Semangat besar tanpa arah: ide bermunculan tetapi sulit diselesaikan, atau kabar yang ditunggu belum datang. Fokus dan konsistensi perlu dilatih.', 'Seorang pemuda berjubah kuning bermotif salamander berdiri di padang pasir, menggenggam dan menatap tongkat yang bertunas. Piramida jauh terlihat di bawah langit kuning pucat, dan topi berbulunya melambai — lambang rasa ingin tahu dan kabar baru.', 'Ikuti rasa ingin tahumu, tetapi tulis rencana sederhana agar semangat tidak berhenti di ide.', 'Pilih satu ide dan selesaikan versi kecilnya sebelum beralih ke yang lain.', 1, -1),
  ('knight-of-wands', 'Knight of Wands', 12, 'minor', 'wands', 33, '/cards/knight-of-wands.svg', array['petualangan', 'gairah', 'energi tinggi', 'keberanian', 'spontanitas']::text[], array['gegabah', 'tidak sabar', 'cepat marah', 'kurang arah', 'meninggalkan begitu saja']::text[], 'Kesatria berkuda melesat menuju tujuan dengan semangat membara. Sosok atau sikap ini penuh energi, berani, dan menarik, tetapi cenderung bergerak lebih cepat daripada pertimbangannya.', 'Energi berapi-api berubah jadi gegabah, tidak sabar, atau mudah beralih. Bisa juga semangatmu padam di tengah jalan karena tujuan kurang jelas.', 'Seorang kesatria berzirah dengan jubah bermotif salamander menunggang kuda yang sedang melonjak di padang pasir, menggenggam tongkat berdaun. Piramida berdiri jauh di belakang dan bulu merah-oranye di helmnya berkibar — lambang gairah dan perjalanan.', 'Gunakan energimu untuk satu tujuan jelas, dan beri jeda sebelum bereaksi.', 'Lambatkan langkah dan periksa arah; semangat yang terarah jauh lebih efektif daripada yang meledak-ledak.', 1, -1),
  ('queen-of-wands', 'Queen of Wands', 13, 'minor', 'wands', 34, '/cards/queen-of-wands.svg', array['percaya diri', 'hangat', 'karisma', 'kemandirian', 'semangat hidup']::text[], array['cemburu', 'egois', 'menuntut perhatian', 'kurang percaya diri', 'emosi meledak']::text[], 'Ratu bertakhta dengan bunga matahari dan kucing hitam di sisinya: hangat, karismatik, dan yakin pada dirinya. Sosok atau sikap ini menginspirasi, mandiri, dan berani tampil apa adanya.', 'Kepercayaan diri bergeser menjadi cemburu, dominasi, atau sebaliknya meredup. Kehangatan perlu dijaga agar tidak berubah menjadi tuntutan akan perhatian.', 'Seorang ratu duduk di singgasana berukir singa, memegang tongkat berdaun dan bunga matahari. Seekor kucing hitam duduk di kakinya dan jubah kuningnya melambai di depan gunung dan piramida — lambang karisma dan vitalitas.', 'Berdirilah dengan percaya diri pada nilaimu dan sebarkan kehangatan tanpa perlu membuktikan apa-apa.', 'Kenali sumber cemburu atau tuntutanmu, dan kembalikan rasa percaya diri lewat tindakan kecil yang menguatkan.', 2, -1),
  ('king-of-wands', 'King of Wands', 14, 'minor', 'wands', 35, '/cards/king-of-wands.svg', array['visi', 'kepemimpinan', 'karisma', 'inisiatif', 'wibawa']::text[], array['otoriter', 'tidak sabar', 'ego besar', 'visi kabur', 'impulsif']::text[], 'Raja bertakhta dengan salamander di jubahnya: pemimpin visioner yang mengubah ide menjadi gerakan. Sosok atau sikap ini percaya diri, bertanggung jawab, dan mampu menginspirasi orang lain.', 'Kepemimpinan berubah menjadi dominasi atau ketidaksabaran, atau visi yang kabur membuat arah tidak jelas. Ambisi perlu diimbangi dengan mendengarkan.', 'Seorang raja duduk di singgasana berukir singa dan salamander, menggenggam tongkat yang bertunas dengan jubah oranye-merah dan mahkota. Salamander kecil berada di kakinya di depan gunung kuning — lambang kepemimpinan dan visi.', 'Pegang visimu dengan jelas dan pimpin dengan teladan, bukan dengan tekanan.', 'Dengarkan masukan sebelum memutuskan, dan jernihkan kembali visi agar timmu tahu ke mana melangkah.', 1, -1),
  ('ace-of-cups', 'Ace of Cups', 1, 'minor', 'cups', 36, '/cards/ace-of-cups.svg', array['cinta baru', 'kelimpahan emosi', 'welas asih', 'intuisi', 'hati terbuka']::text[], array['perasaan terpendam', 'emosi tertahan', 'kekosongan', 'menutup hati', 'luapan emosi']::text[], 'Sebuah cawan dari awan meluap air kehidupan dan merpati membawa hosti. Hatimu terbuka pada kasih, kreativitas, dan pemulihan emosi yang tulus.', 'Aliran perasaan tersumbat: kamu menahan emosi, merasa kosong, atau takut membuka hati lagi. Air tetap ada, hanya perlu dialirkan perlahan.', 'Sebuah tangan dari awan menopang cawan yang meluapkan lima aliran air ke kolam berteratai di bawahnya. Seekor merpati putih menjatuhkan hosti bersalib ke dalam cawan di bawah langit cerah — lambang kasih dan awal emosional.', 'Beri ruang bagi perasaanmu mengalir lewat percakapan jujur, tulisan, atau seni.', 'Pelan-pelan buka hati pada satu orang atau satu kegiatan yang aman bagimu, tanpa memaksa.', 2, -1),
  ('two-of-cups', 'Two of Cups', 2, 'minor', 'cups', 37, '/cards/two-of-cups.svg', array['kemitraan', 'saling tertarik', 'keselarasan', 'kesepakatan', 'timbal balik']::text[], array['ketidakselarasan', 'putus komunikasi', 'ketimpangan', 'tarik ulur', 'jarak']::text[], 'Dua orang bertukar cawan di bawah lambang singa bersayap: pertemuan setara yang saling menghormati. Ini tentang ikatan, kesepakatan, dan ketertarikan yang berjalan dua arah.', 'Keseimbangan terganggu: salah satu memberi lebih, komunikasi terputus, atau perasaan tidak sejalan. Cari kembali kesetaraan sebelum jarak melebar.', 'Seorang pria dan seorang perempuan berhadapan, saling mengangkat cawan di tangan mereka dengan mahkota bunga dan karangan daun di kepala. Di antara mereka melayang caduceus berkepala singa bersayap, dan rumah-rumah di bukit tampak jauh — lambang ikatan yang setara.', 'Hargai sesuatu dari orang di depanmu dan ungkapkan secara langsung hari ini.', 'Bicarakan ketimpangan dengan lembut dan sepakati cara berbagi yang terasa adil.', 2, -1),
  ('three-of-cups', 'Three of Cups', 3, 'minor', 'cups', 38, '/cards/three-of-cups.svg', array['perayaan', 'persahabatan', 'komunitas', 'kegembiraan bersama', 'dukungan']::text[], array['gosip', 'berlebihan', 'terisolasi', 'kelompok pecah', 'pesta tanpa arti']::text[], 'Tiga perempuan mengangkat cawan di tengah panen. Kartu ini merayakan persahabatan, dukungan, dan sukacita yang dibagi bersama komunitas.', 'Kebersamaan memudar atau berubah menjadi gosip, hura-hura berlebihan, atau rasa tersisih dari kelompok. Cari lingkaran yang menopangmu dengan tulus.', 'Tiga perempuan berjubah warna berbeda dan bermahkota bunga menari sambil mengangkat cawan, dikelilingi buah-buahan dan labu di ladang. Mereka tampak bahagia di bawah langit cerah — lambang persahabatan dan panen bersama.', 'Rayakan sesuatu bersama orang-orang yang menghangatkanmu, entah kecil atau besar.', 'Pilih lingkaran yang sehat, dan hindari terbawa pesta atau obrolan yang menjatuhkan orang lain.', 2, -1),
  ('four-of-cups', 'Four of Cups', 4, 'minor', 'cups', 39, '/cards/four-of-cups.svg', array['perenungan', 'apatis', 'peluang terlewat', 'ketidakpuasan', 'menarik diri']::text[], array['kesadaran baru', 'bangkit dari apatis', 'tawaran diterima', 'motivasi kembali', 'melihat peluang']::text[], 'Duduk di bawah pohon dengan tangan terlipat, sosok ini mengabaikan cawan yang ditawarkan dari awan. Kebosanan atau ketidakpuasan membuatmu menutup mata dari peluang yang ada di depanmu.', 'Kamu mulai tersadar dari kebosanan dan melihat tawaran yang sebelumnya terlewat. Semangat perlahan kembali dan hati lebih terbuka.', 'Seorang pemuda duduk bersila di bawah pohon dengan tangan terlipat dan wajah tertunduk. Tiga cawan berdiri di depannya sementara sebuah cawan keempat disodorkan tangan dari awan, tampak tak ia sadari — lambang apatis dan perenungan.', 'Tanyakan apa yang sebenarnya kamu inginkan, dan lihat ulang peluang yang selama ini diabaikan.', 'Ambil satu tawaran kecil dengan terbuka dan lihat bagaimana perasaanmu setelahnya.', -1, 1),
  ('five-of-cups', 'Five of Cups', 5, 'minor', 'cups', 40, '/cards/five-of-cups.svg', array['kehilangan', 'penyesalan', 'duka', 'fokus pada yang hilang', 'kekecewaan']::text[], array['menerima', 'berdamai', 'bangkit', 'melihat yang tersisa', 'pemulihan']::text[], 'Sosok berjubah hitam menunduk pada tiga cawan yang tumpah, tanpa menoleh pada dua cawan yang masih tegak. Kesedihan itu nyata, tetapi ada yang masih bisa diselamatkan jika kamu menoleh.', 'Kamu mulai berdamai dengan kehilangan dan melihat yang masih tersisa. Proses duka belum tentu selesai, tetapi pandanganmu mulai bergeser.', 'Seorang sosok berjubah hitam membungkuk menatap tiga cawan yang tumpah dengan cairan merah di tanah. Dua cawan masih tegak di belakangnya, sungai mengalir di samping, dan jembatan menuju rumah di kejauhan — lambang duka dan harapan tersisa.', 'Beri dirimu waktu berduka, lalu perlahan lihat apa yang masih tersisa dan layak dirawat.', 'Lanjutkan proses berdamai dengan kehilanganmu dan izinkan dirimu bergerak selangkah demi selangkah.', -1, 1),
  ('six-of-cups', 'Six of Cups', 6, 'minor', 'cups', 41, '/cards/six-of-cups.svg', array['nostalgia', 'kenangan masa kecil', 'kebaikan sederhana', 'reuni', 'kepolosan']::text[], array['terjebak masa lalu', 'idealisasi', 'melepas kenangan', 'dewasa', 'kenaifan']::text[], 'Dua anak bertukar cawan berisi bunga di halaman yang hangat. Kartu ini membawa nostalgia, kebaikan tulus, dan hubungan dengan masa lalu yang menyenangkan, entah orang lama atau kenangan manis.', 'Kenangan menahanmu: kamu mengidealkan masa lalu atau sulit beranjak dari yang dulu. Hargai kenangannya sambil melangkah ke masa kini.', 'Seorang anak lebih besar menyerahkan cawan berisi bunga putih kepada anak yang lebih kecil di halaman rumah berlantai batu. Lima cawan berbunga lain berdiri di sekitar mereka, dan seorang penjaga berjalan di kejauhan — lambang kenangan dan kebaikan.', 'Hubungi seseorang dari masa lalu yang berkesan atau lakukan hal sederhana yang mengingatkanmu pada kegembiraan lama.', 'Hargai kenangan, tetapi pastikan kamu tidak membandingkan masa kini dengan versi masa lalu yang terlalu indah.', 1, 0),
  ('seven-of-cups', 'Seven of Cups', 7, 'minor', 'cups', 42, '/cards/seven-of-cups.svg', array['banyak pilihan', 'angan-angan', 'ilusi', 'godaan', 'kebingungan']::text[], array['kejelasan', 'memilih', 'menghindari ilusi', 'fokus', 'realistis']::text[], 'Sosok bersiluet menatap tujuh cawan mengambang di awan, masing-masing berisi hal menggoda. Banyak kemungkinan terlihat indah, tetapi tidak semuanya nyata. Saatnya memilah antara angan dan rencana.', 'Kabut pilihan mulai terangkat: kamu melihat mana yang realistis dan siap menentukan satu arah. Atau kamu justru semakin terpecah di antara banyak opsi.', 'Seorang sosok berbayang berdiri menghadap tujuh cawan di awan, berisi kepala, ular, kastil, permata, laurel, naga, dan siluet berselubung. Warna-warna menyala di langit gelap, mengaburkan mana yang nyata — lambang ilusi dan pilihan.', 'Tuliskan semua pilihanmu, lalu tandai mana yang realistis dan sesuai nilai, dan mulailah dari satu.', 'Kurangi opsi hingga dua atau tiga, uji dengan langkah kecil, dan berhenti membandingkan tanpa mencoba.', 0, 1),
  ('eight-of-cups', 'Eight of Cups', 8, 'minor', 'cups', 43, '/cards/eight-of-cups.svg', array['melangkah pergi', 'pencarian makna', 'melepas', 'ketidakpuasan batin', 'perjalanan emosi']::text[], array['ragu pergi', 'bertahan tanpa alasan', 'takut perubahan', 'kembali', 'melarikan diri']::text[], 'Di bawah bulan, sosok berjubah meninggalkan delapan cawan yang tertata rapi, menuju pegunungan. Ada yang terasa tidak lagi cukup, dan kamu berani pergi demi sesuatu yang lebih bermakna.', 'Kamu ragu meninggalkan situasi yang sudah tidak memuaskan, atau pergi tanpa menghadapi alasan sebenarnya. Periksa apakah kamu melangkah menuju sesuatu atau hanya lari.', 'Seorang sosok berjubah merah dengan tongkat berjalan memunggungi delapan cawan yang tersusun, menuju pegunungan di bawah bulan sabit dan bulan penuh. Sungai berkelok di sampingnya dalam suasana sunyi — lambang meninggalkan demi pencarian.', 'Akui apa yang tidak lagi memberimu makna, dan rencanakan langkah keluarnya dengan sadar.', 'Jujur pada dirimu: apakah kamu bertahan karena nyaman atau pergi karena menghindar?', -1, -1),
  ('nine-of-cups', 'Nine of Cups', 9, 'minor', 'cups', 44, '/cards/nine-of-cups.svg', array['kepuasan', 'harapan terkabul', 'kenyamanan', 'syukur', 'kebahagiaan']::text[], array['kepuasan semu', 'serakah', 'kurang bersyukur', 'hampa', 'kebahagiaan dangkal']::text[], 'Sosok duduk puas dengan sembilan cawan tertata di belakangnya. Ini kartu harapan yang terkabul, kenyamanan, dan kemampuan menikmati apa yang sudah kamu raih.', 'Kepuasan terasa kosong atau berbalik jadi keserakahan. Kamu mungkin mendapatkan yang diinginkan tetapi tetap merasa kurang. Cari apa yang benar-benar mengisi hati.', 'Seorang pria gemuk berjenggot duduk di bangku dengan tangan terlipat dan topi merah, di depan meja berkain biru yang menyangga sembilan cawan berkilau. Langit kuning cerah menaungi suasana yang puas dan hangat — lambang pemenuhan keinginan.', 'Nikmati apa yang sudah kamu capai dan ungkapkan rasa syukur pada orang yang membantumu.', 'Tanyakan apa yang sebenarnya kamu cari di balik hal yang kamu kejar, dan nikmati yang sudah ada.', 2, 0),
  ('ten-of-cups', 'Ten of Cups', 10, 'minor', 'cups', 45, '/cards/ten-of-cups.svg', array['keluarga bahagia', 'harmoni', 'kepenuhan emosi', 'pelangi', 'kebersamaan']::text[], array['keluarga retak', 'harmoni semu', 'nilai tidak sejalan', 'tekanan citra', 'ketegangan rumah']::text[], 'Pelangi sepuluh cawan menaungi keluarga yang bergandengan tangan. Kartu ini melambangkan kebahagiaan yang utuh: kasih, rasa aman, dan nilai bersama yang dinikmati bersama orang tercinta.', 'Gambar keluarga ideal tak sepenuhnya cocok dengan kenyataan: ada ketegangan, nilai berbeda, atau tekanan menjaga citra. Harmoni sejati perlu kejujuran.', 'Sepasang orang dewasa berpelukan mengangkat tangan ke langit, sementara dua anak menari di samping. Sepuluh cawan membentuk busur di bawah pelangi, di depan rumah dan sungai yang tenang — lambang kebahagiaan keluarga.', 'Nikmati kebersamaan dengan orang tercinta dan ungkapkan rasa terima kasihmu secara langsung.', 'Jujurlah tentang apa yang terasa tidak selaras, dan bicarakan dengan hangat agar harmoni lebih nyata.', 2, -1),
  ('page-of-cups', 'Page of Cups', 11, 'minor', 'cups', 46, '/cards/page-of-cups.svg', array['pesan hati', 'kepekaan', 'kreativitas', 'kejutan manis', 'imajinasi']::text[], array['terlalu sensitif', 'emosi tidak matang', 'kecewa', 'menghindar', 'kreativitas tersendat']::text[], 'Pemuda menerima ikan yang muncul dari cawan: sebuah kejutan lembut dari dunia perasaan. Sosok atau sikap ini peka, kreatif, dan terbuka pada pesan atau ide yang menyentuh hati.', 'Kepekaan menjadi mudah tersinggung, atau ide kreatif tak kunjung dituangkan. Perasaan perlu dilatih agar tidak mengendalikan keputusan.', 'Seorang pemuda berjubah bunga dan topi biru berdiri di tepi laut, memegang cawan dengan seekor ikan kecil menyembul keluar. Ombak lembut di belakangnya dan ia menatap ikan itu dengan heran — lambang kejutan batin.', 'Terbuka pada pesan atau ide yang datang lewat perasaan, lalu tuangkan dalam bentuk nyata.', 'Kenali emosi yang mudah tersentuh dan beri jeda sebelum bereaksi atau memutuskan.', 1, -1),
  ('knight-of-cups', 'Knight of Cups', 12, 'minor', 'cups', 47, '/cards/knight-of-cups.svg', array['romantis', 'tawaran hati', 'idealis', 'kelembutan', 'mengikuti hati']::text[], array['moody', 'janji manis', 'tidak realistis', 'menghindar', 'rayuan kosong']::text[], 'Kesatria menunggang kuda putih dengan perlahan sambil membawa cawan: sosok atau sikap yang romantis, idealis, dan menawarkan hati. Ia mengikuti perasaan dan menghadirkan keindahan.', 'Romantisme berubah menjadi janji manis tanpa tindakan, mood yang naik turun, atau melarikan diri dari kenyataan. Perlu keseimbangan antara hati dan realitas.', 'Seorang kesatria berzirah bersayap di helm dan sepatunya menunggang kuda putih dengan langkah tenang, memegang cawan di tangannya. Sungai berkelok dan pegunungan membentang di belakangnya di bawah langit cerah — lambang romansa dan idealisme.', 'Ungkapkan perasaanmu dengan tulus lalu wujudkan lewat tindakan yang konsisten.', 'Lihat kenyataan di balik kata-kata manis, dan pastikan perasaan disertai langkah nyata.', 1, -1),
  ('queen-of-cups', 'Queen of Cups', 13, 'minor', 'cups', 48, '/cards/queen-of-cups.svg', array['empati', 'intuisi', 'kasih sayang', 'ketenangan batin', 'kepekaan']::text[], array['terlalu larut', 'batas kabur', 'emosi tidak stabil', 'martir', 'mengabaikan diri']::text[], 'Ratu duduk di tepi laut menatap cawan tertutupnya: sosok atau sikap yang penuh empati, intuitif, dan menenangkan. Ia memahami perasaan tanpa tenggelam di dalamnya.', 'Empati berubah menjadi larut dalam emosi orang lain, batas menjadi kabur, atau kamu mengabaikan diri demi merawat orang lain. Kembalikan keseimbangan antara peduli dan menjaga diri.', 'Seorang ratu bermahkota duduk di singgasana berukir kerang di tepi laut, memandang cawan berhias tertutup di tangannya. Gelombang menyentuh kakinya dan kerikil berwarna tersebar di sekitarnya — lambang kedalaman perasaan dan intuisi.', 'Dengarkan intuisi dan hadirlah dengan empati, sambil menjaga ruang batinmu sendiri.', 'Tetapkan batas yang lembut agar kepedulianmu tidak menguras dirimu.', 2, -1),
  ('king-of-cups', 'King of Cups', 14, 'minor', 'cups', 49, '/cards/king-of-cups.svg', array['kematangan emosi', 'ketenangan', 'diplomasi', 'kebijaksanaan hati', 'pengendalian']::text[], array['manipulasi emosi', 'menekan perasaan', 'moody', 'dingin', 'tidak stabil']::text[], 'Raja duduk tenang di singgasana di tengah laut yang bergelombang: ia menguasai perasaannya tanpa menekannya. Sosok atau sikap ini bijak, stabil, dan mampu memberi dukungan dalam situasi emosional.', 'Emosi ditekan atau meluap tanpa kendali, atau ada manipulasi halus lewat perasaan. Kematangan butuh kejujuran terhadap apa yang dirasakan.', 'Seorang raja bermahkota duduk di singgasana batu yang mengambang di laut, memegang cawan dan tongkat kerajaan. Ikan melompat di sisi kiri dan kapal berlayar di sisi kanan, dengan kalung ikan di lehernya — lambang kendali emosional.', 'Hadapi situasi emosional dengan tenang dan tetap jujur pada perasaanmu.', 'Akui perasaan yang selama ini kamu tekan, dan bicarakan tanpa menyalahkan.', 1, -1),
  ('ace-of-swords', 'Ace of Swords', 1, 'minor', 'swords', 50, '/cards/ace-of-swords.svg', array['kejernihan', 'terobosan pikiran', 'kebenaran', 'keputusan tegas', 'ide tajam']::text[], array['kebingungan', 'komunikasi kasar', 'pikiran kabur', 'keputusan tergesa', 'kata melukai']::text[], 'Tangan dari awan mengangkat pedang bermahkota laurel: pikiranmu menjadi tajam dan jernih. Sebuah kebenaran, ide, atau keputusan penting terlihat jelas dan siap dipakai dengan adil.', 'Pikiran kusut atau kata-kata digunakan tanpa pertimbangan sehingga melukai. Jernihkan dulu sebelum memotong atau menyimpulkan.', 'Sebuah tangan dari awan menggenggam pedang tegak lurus yang ujungnya ditempati mahkota emas berhias laurel dan daun palem. Pegunungan tandus berdiri di bawah, dan butiran cahaya jatuh dari awan — lambang kebenaran dan kejernihan.', 'Tulis apa yang sebenarnya kamu pikirkan, lalu ucapkan dengan jelas dan adil.', 'Tunda kata-kata tajam dan jernihkan dulu pikiranmu dengan menuliskan fakta satu per satu.', 1, -1),
  ('two-of-swords', 'Two of Swords', 2, 'minor', 'swords', 51, '/cards/two-of-swords.svg', array['kebuntuan', 'menahan keputusan', 'menghindar', 'keseimbangan rapuh', 'menutup mata']::text[], array['kebuntuan pecah', 'informasi terungkap', 'kebingungan', 'keputusan terpaksa', 'kecemasan']::text[], 'Sosok berpenutup mata duduk menyilangkan dua pedang di depan dada, laut di belakangnya. Kamu menahan diri dari memilih atau menolak melihat kenyataan karena takut terluka. Kebuntuan perlu dipecahkan dengan informasi dan kejujuran.', 'Penutup mata mulai terlepas: informasi baru atau keberanian menghadapi kenyataan memecah kebuntuan. Namun bisa juga kebingunganmu membesar karena terlalu lama menunda.', 'Seorang perempuan duduk di bangku batu dengan mata tertutup kain putih, menyilangkan dua pedang di dadanya. Laut tenang dengan batu-batu dan bulan sabit di belakangnya di bawah langit malam pucat — lambang kebuntuan dan penghindaran.', 'Lepas penutup mata: kumpulkan informasi, bicarakan yang dihindari, lalu putuskan dengan jujur.', 'Pilih satu langkah kecil untuk memecah kebuntuan, dan jangan biarkan takut membuatmu berhenti bergerak.', 0, -1),
  ('three-of-swords', 'Three of Swords', 3, 'minor', 'swords', 52, '/cards/three-of-swords.svg', array['patah hati', 'kesedihan', 'kebenaran menyakitkan', 'kehilangan', 'penyembuhan dimulai']::text[], array['pulih', 'melepas luka', 'memendam sakit', 'memaafkan', 'luka lama']::text[], 'Hati ditembus tiga pedang di bawah hujan: rasa sakit emosional yang nyata, entah karena kehilangan, pengkhianatan, atau kebenaran yang sulit diterima. Mengakui sakit adalah langkah awal penyembuhan.', 'Luka mulai pulih, atau justru dipendam dan terus menekan. Memaafkan dan melepas butuh waktu; jangan terburu-buru memaksa dirimu merasa baik.', 'Sebuah hati merah ditembus tiga pedang di tengah langit kelabu yang dihujani awan gelap. Tak ada sosok manusia, hanya hati yang berdarah di antara hujan deras — lambang duka dan patah hati.', 'Beri dirimu izin merasakan sakit itu dan cari dukungan orang yang kamu percaya.', 'Biarkan penyembuhan berjalan sesuai ritmemu, dan ceritakan lukamu agar tidak menumpuk sendirian.', -2, 0),
  ('four-of-swords', 'Four of Swords', 4, 'minor', 'swords', 53, '/cards/four-of-swords.svg', array['istirahat', 'pemulihan', 'jeda', 'kontemplasi', 'ketenangan']::text[], array['gelisah', 'kelelahan', 'kembali beraktivitas', 'menolak istirahat', 'burnout']::text[], 'Sosok berbaring tenang di makam batu dengan tiga pedang menggantung dan satu di bawah. Ini saat beristirahat, memulihkan tenaga, dan menenangkan pikiran sebelum melangkah lagi.', 'Kamu gelisah dan tidak bisa berhenti, atau mulai bangkit setelah masa istirahat. Jika terus memaksa, kelelahan akan datang lebih keras.', 'Seorang ksatria berbaring di atas peti batu dengan tangan terlipat berdoa. Di dinding ada jendela kaca patri dengan sosok memberkati, tiga pedang tergantung di dinding dan satu terbaring di bawahnya — lambang istirahat dan penyembuhan.', 'Jadwalkan jeda yang sungguh-sungguh: tidur, hening, dan menjauh dari tuntutan sebentar.', 'Izinkan dirimu beristirahat tanpa rasa bersalah, lalu kembali perlahan dengan batas yang jelas.', 0, -1),
  ('five-of-swords', 'Five of Swords', 5, 'minor', 'swords', 54, '/cards/five-of-swords.svg', array['konflik', 'menang dengan harga', 'ego', 'perselisihan', 'strategi licik']::text[], array['rekonsiliasi', 'penyesalan', 'melepas dendam', 'menyerah', 'perdamaian']::text[], 'Sosok tersenyum memungut pedang sementara dua lainnya pergi dengan kecewa. Kemenangan yang diraih lewat mengalahkan orang lain bisa mahal harganya. Pertimbangkan apakah menang debat sebanding dengan hubungan yang retak.', 'Kamu mulai menyesali pertengkaran atau siap berdamai. Atau dendam masih tertahan. Berdamai dengan ego lebih berharga daripada membuktikan diri.', 'Seorang pria tersenyum memegang tiga pedang sementara dua sosok lain berjalan menjauh dengan bahu merosot di tepi laut. Langit bergolak berwarna kuning pekat dan awan gelap — lambang kemenangan yang hampa.', 'Tanyakan apa yang sebenarnya ingin kamu capai dari konflik ini, dan pilih pertarungan yang pantas.', 'Ulurkan tangan lebih dulu bila perlu; berdamai lebih penting daripada memenangkan argumen.', -1, 0),
  ('six-of-swords', 'Six of Swords', 6, 'minor', 'swords', 55, '/cards/six-of-swords.svg', array['peralihan', 'meninggalkan kesulitan', 'perjalanan tenang', 'pemulihan', 'bergerak maju']::text[], array['terjebak', 'beban dibawa', 'peralihan sulit', 'enggan pergi', 'masalah menyusul']::text[], 'Perahu membawa sosok berselubung dan seorang anak menyeberang menuju air yang lebih tenang. Kamu meninggalkan masa sulit dan bergerak ke keadaan yang lebih damai, walau bawaan lama masih terasa.', 'Peralihan terasa tersendat: kamu sulit meninggalkan kesulitan, atau masalah lama ikut terbawa. Sadari beban yang masih kamu pikul agar perjalanan lebih ringan.', 'Seorang sosok berselubung berdiri di perahu bersama seorang anak, sementara nelayan berpakaian menggerakkan galah. Enam pedang tegak di perahu itu dan air di sisi kanan lebih tenang dari sisi kiri yang bergelombang — lambang peralihan.', 'Teruskan perjalanan menuju keadaan yang lebih tenang dan biarkan dirimu menerima bantuan.', 'Kenali beban lama yang masih kamu bawa dan putuskan mana yang bisa diturunkan.', 1, -1),
  ('seven-of-swords', 'Seven of Swords', 7, 'minor', 'swords', 56, '/cards/seven-of-swords.svg', array['strategi', 'siasat', 'menghindari', 'tidak terus terang', 'diam-diam']::text[], array['pengakuan', 'ketahuan', 'kejujuran', 'rasa bersalah', 'siasat gagal']::text[], 'Sosok mengendap-endap membawa lima pedang meninggalkan tenda. Kartu ini bisa menunjuk siasat, rahasia, atau tindakan yang tidak sepenuhnya terus terang. Periksa apakah ada yang disembunyikan, termasuk olehmu.', 'Rahasia terbuka atau kamu memutuskan jujur. Hati nurani bisa menekan, dan lebih baik menyelesaikan daripada terus bersembunyi.', 'Seorang pria berjubah dan bertopi merah berjalan berjingkat dengan lima pedang di pelukannya, meninggalkan dua pedang tertancap di tanah. Kemah-kemah dan orang-orang di kejauhan tampak tidak sadar di bawah langit kuning — lambang siasat dan pengelakan.', 'Jujurlah tentang apa yang kamu hindari, dan pilih transparansi daripada jalan pintas.', 'Akui yang perlu diakui dan perbaiki dengan cara terang agar beban di hatimu berkurang.', -1, 0),
  ('eight-of-swords', 'Eight of Swords', 8, 'minor', 'swords', 57, '/cards/eight-of-swords.svg', array['terjebak', 'pembatasan diri', 'rasa tak berdaya', 'ketakutan', 'persepsi sempit']::text[], array['pembebasan', 'melepas ikatan', 'melihat jalan keluar', 'keberanian', 'kesadaran']::text[], 'Sosok berpenutup mata dan terikat longgar dikelilingi pedang: terasa terkurung padahal celah jalan keluar ada. Banyak keterbatasan datang dari cara pandang dan rasa takut yang bisa kamu uji ulang.', 'Ikatan mulai terlepas dan kamu melihat jalan keluar. Kesadaran bahwa kamu punya pilihan membuka keberanian untuk bergerak.', 'Seorang perempuan berdiri dengan mata tertutup dan tubuh terikat longgar kain, dikelilingi delapan pedang tertancap di tanah becek. Sebuah kastil berdiri di bukit jauh di bawah langit kelabu — lambang rasa terperangkap yang sebagian dibangun sendiri.', 'Tuliskan pembatas yang kamu rasakan, lalu uji satu per satu: mana yang fakta, mana yang ketakutan.', 'Ambil satu langkah kecil keluar dari pola lama; kamu punya lebih banyak pilihan daripada yang terlihat.', -1, 1),
  ('nine-of-swords', 'Nine of Swords', 9, 'minor', 'swords', 58, '/cards/nine-of-swords.svg', array['kecemasan', 'insomnia pikiran', 'rasa bersalah', 'kekhawatiran', 'mimpi buruk']::text[], array['kecemasan mereda', 'mencari bantuan', 'harapan', 'melepas khawatir', 'beban batin']::text[], 'Duduk di tempat tidur di tengah malam sambil menutup wajah, sosok ini diliputi pikiran yang menyiksa. Banyak kecemasan membesar di kepala dan terasa lebih berat daripada kenyataannya. Ceritakan kepada seseorang yang kamu percaya.', 'Kecemasan mulai mereda karena kamu berbagi atau mencari dukungan. Atau beban batin yang lama dipendam butuh dibicarakan. Kamu tidak harus menanggungnya sendirian.', 'Seorang sosok terduduk di tempat tidur dengan wajah dalam telapak tangan, di kamar gelap berselimut bunga dan lambang astrologi. Sembilan pedang tergantung horizontal di dinding di atasnya — lambang kecemasan malam hari.', 'Tuliskan kekhawatiranmu dan bagikan dengan seseorang yang tepercaya, atau profesional jika perlu.', 'Teruskan mencari dukungan dan rutinitas menenangkan; kamu pantas mendapat bantuan.', -2, 0),
  ('ten-of-swords', 'Ten of Swords', 10, 'minor', 'swords', 59, '/cards/ten-of-swords.svg', array['akhir yang menyakitkan', 'titik terendah', 'pelepasan', 'pengkhianatan', 'fajar setelah gelap']::text[], array['pemulihan', 'bangkit', 'bertahan di luka', 'drama berlebihan', 'melepas']::text[], 'Sepuluh pedang menancap di punggung sosok yang tertelungkup, tetapi fajar sudah terbit di cakrawala. Sesuatu berakhir dengan menyakitkan; ini titik terendah, dan setelahnya hanya ada jalan naik.', 'Kamu mulai bangkit dari keterpurukan, atau justru terus mengulang drama kehilangan yang sama. Cahaya fajar tetap ada saat kamu siap melihatnya.', 'Seorang sosok tertelungkup di tanah dengan sepuluh pedang menancap di punggungnya, jubah merah menutupi sebagian tubuhnya. Langit hitam di atas, tetapi di cakrawala fajar kuning menyingsing di atas laut tenang — lambang akhir dan awal baru.', 'Terima bahwa fase ini telah berakhir, dan cari dukungan sambil menunggu fajar.', 'Berhenti mengulang cerita luka; pilih satu langkah pemulihan kecil dan jalani hari ini.', -2, 0),
  ('page-of-swords', 'Page of Swords', 11, 'minor', 'swords', 60, '/cards/page-of-swords.svg', array['rasa ingin tahu', 'kewaspadaan', 'ide baru', 'komunikasi', 'belajar']::text[], array['bicara tanpa pikir', 'gosip', 'terburu-buru', 'kritik tajam', 'tidak fokus']::text[], 'Pemuda berdiri di bukit berangin sambil memegang pedang tegak, matanya awas. Sosok atau sikap ini cerdas, haus informasi, dan siap belajar atau mengajukan pertanyaan tajam.', 'Keingintahuan berubah jadi gosip, ucapan yang melukai, atau pikiran yang melompat ke mana-mana. Pertimbangkan kata sebelum diucapkan.', 'Seorang pemuda berdiri di bukit berangin dengan pedang yang diangkat tegak dengan kedua tangan, rambutnya melambai. Awan beriak di langit dan burung terbang jauh di belakang — lambang kewaspadaan dan rasa ingin tahu.', 'Ajukan pertanyaan yang jernih dan kumpulkan informasi sebelum bersikap.', 'Tahan komentar spontan, cek fakta, dan fokuskan pikiranmu pada satu hal.', 1, -1),
  ('knight-of-swords', 'Knight of Swords', 12, 'minor', 'swords', 61, '/cards/knight-of-swords.svg', array['tegas', 'cepat bertindak', 'ambisi', 'argumentatif', 'fokus tujuan']::text[], array['gegabah', 'agresif', 'tidak peka', 'terburu-buru', 'berubah arah']::text[], 'Kesatria menerjang di atas kuda ke arah badai dengan pedang terangkat. Sosok atau sikap ini cerdas, berani, dan fokus pada tujuan, tetapi cenderung melaju tanpa melihat sekelilingnya.', 'Kecepatan dan ketegasan berubah menjadi agresi, kata-kata tajam, atau tindakan gegabah. Perlambat dan lihat dampaknya pada orang lain.', 'Seorang kesatria berzirah menunggang kuda putih yang berlari kencang dengan pedang terangkat. Pohon-pohon condong ditiup angin dan awan bergulung di langit — lambang dorongan cepat dan pikiran yang tajam.', 'Arahkan ketegasanmu ke satu tujuan, dan periksa dulu jalurnya agar tidak menabrak orang.', 'Perlambat langkah dan pilih kata dengan hati-hati; kecepatan tanpa arah hanya menguras tenaga.', 0, -1),
  ('queen-of-swords', 'Queen of Swords', 13, 'minor', 'swords', 62, '/cards/queen-of-swords.svg', array['jernih', 'mandiri', 'jujur lugas', 'batas tegas', 'bijak dari pengalaman']::text[], array['dingin', 'sinis', 'terlalu kritis', 'menutup diri', 'tajam melukai']::text[], 'Ratu duduk tegak di langit tinggi sambil mengangkat pedang dan satu tangan terbuka. Sosok atau sikap ini jernih, mandiri, dan jujur, tahu apa yang dia mau, dan bijak dari pengalaman pahit.', 'Ketajaman berubah jadi sinisme, dingin, atau kritik yang melukai. Kebijaksanaan tetap ada, tetapi perlu dilembutkan dengan empati.', 'Seorang ratu bermahkota kupu-kupu duduk di singgasana berukir di puncak, memegang pedang tegak dan mengulurkan tangan kiri. Awan menggulung di langit dan burung terbang di atasnya — lambang kejernihan dan kemandirian.', 'Berbicaralah dengan jujur dan jelas, dan pegang batasmu dengan tenang.', 'Lembutkan ketajamanmu dengan empati, dan biarkan kepercayaan tumbuh pelan-pelan.', 1, -1),
  ('king-of-swords', 'King of Swords', 14, 'minor', 'swords', 63, '/cards/king-of-swords.svg', array['logika', 'otoritas intelektual', 'keadilan', 'kejelasan', 'keputusan objektif']::text[], array['dingin', 'manipulatif', 'kritik berlebihan', 'otoriter', 'tidak peka']::text[], 'Raja duduk tegak dengan pedang terangkat, pikirannya jernih dan adil. Sosok atau sikap ini mengandalkan logika, integritas, dan kemampuan memutuskan secara objektif.', 'Logika yang dingin, kritik berlebihan, atau memakai pengetahuan untuk menekan orang lain. Keadilan sejati juga membutuhkan hati.', 'Seorang raja bermahkota duduk di singgasana menghadap lurus ke depan sambil mengangkat pedang tegak dengan satu tangan. Tirai biru dan awan bergulung di belakangnya dengan burung di langit — lambang akal dan keadilan.', 'Putuskan berdasarkan fakta dan prinsip, lalu jelaskan alasannya dengan terang.', 'Seimbangkan logika dengan empati; keputusan yang adil tetap memperhatikan manusianya.', 1, -1),
  ('ace-of-pentacles', 'Ace of Pentacles', 1, 'minor', 'pentacles', 64, '/cards/ace-of-pentacles.svg', array['peluang nyata', 'benih kemakmuran', 'awal stabil', 'kesempatan', 'fondasi']::text[], array['peluang terlewat', 'perencanaan buruk', 'awal goyah', 'tertunda', 'pemborosan']::text[], 'Tangan dari awan menyodorkan koin emas di atas taman subur: peluang nyata untuk membangun sesuatu yang stabil. Benih kecil dengan perawatan yang tepat dapat tumbuh menjadi kemakmuran.', 'Peluang terlewat karena kurang persiapan, atau awal yang goyah karena perencanaan buruk. Perbaiki fondasi sebelum menanam lebih banyak.', 'Sebuah tangan dari awan menopang koin emas berpentagram di atas taman berbunga yang rindang. Jalan setapak melewati lengkung pagar dedaunan menuju pegunungan jauh — lambang peluang material dan fondasi stabil.', 'Ambil peluang nyata yang ada di depanmu dan mulai dengan langkah kecil yang bisa dikelola.', 'Perkuat fondasi dulu: rencana, dana cadangan, dan kesiapanmu, sebelum memperbesar skala.', 2, -1),
  ('two-of-pentacles', 'Two of Pentacles', 2, 'minor', 'pentacles', 65, '/cards/two-of-pentacles.svg', array['menyeimbangkan', 'fleksibilitas', 'prioritas', 'adaptasi', 'multitasking']::text[], array['kewalahan', 'tidak seimbang', 'kekacauan', 'terlalu banyak', 'prioritas kabur']::text[], 'Sosok menari sambil menjaga dua koin dalam lingkaran tak terhingga di tengah ombak. Kamu menyeimbangkan beberapa tuntutan sekaligus, dan kelenturan membantu menjaga alirannya.', 'Terlalu banyak bola dalam genggaman: kewalahan, prioritas kabur, dan keseimbangan goyah. Saatnya memilih apa yang benar-benar perlu dijaga.', 'Seorang pemuda bertopi tinggi menari di atas tanah sambil memainkan dua koin yang terhubung pita berbentuk tak terhingga. Dua kapal besar naik-turun di ombak di belakangnya — lambang keseimbangan dan adaptasi.', 'Atur prioritas, jadwalkan ruang untuk tiap tanggung jawab, dan lentur saat keadaan berubah.', 'Kurangi satu beban yang tidak penting agar keseimbangan lebih mudah dijaga.', 0, -1),
  ('three-of-pentacles', 'Three of Pentacles', 3, 'minor', 'pentacles', 66, '/cards/three-of-pentacles.svg', array['kerja sama', 'keahlian', 'kolaborasi', 'pengakuan', 'membangun bersama']::text[], array['kurang kerja sama', 'kualitas rendah', 'tidak selaras', 'pekerjaan setengah hati', 'konflik peran']::text[], 'Seorang pengrajin bekerja di katedral bersama arsitek dan pendeta, merundingkan rancangan. Kartu ini tentang kolaborasi, keahlian, dan hasil bagus yang lahir dari peran yang saling melengkapi.', 'Kerja sama tersendat: peran tidak jelas, standar tidak selaras, atau ada yang bekerja setengah hati. Perjelas harapan agar hasil tidak menurun.', 'Seorang pengrajin berdiri di atas bangku mengukir lengkung batu di dalam katedral, dengan dua sosok di bawah yang memegang rancangan. Mereka berdiskusi di antara pilar-pilar tinggi — lambang kerja sama dan keahlian.', 'Kerjakan bagianmu dengan baik, dan hargai keahlian orang lain dalam tim.', 'Perjelas peran dan standar kerja, lalu minta masukan secara terbuka.', 1, -1),
  ('four-of-pentacles', 'Four of Pentacles', 4, 'minor', 'pentacles', 67, '/cards/four-of-pentacles.svg', array['keamanan', 'menggenggam', 'penghematan', 'kontrol', 'perlindungan']::text[], array['melepas', 'boros', 'terlalu pelit', 'ketakutan kehilangan', 'keterbukaan']::text[], 'Sosok duduk memeluk satu koin sambil menginjak dua lainnya dan memikul satu di kepala. Rasa aman dibangun dengan menjaga, tetapi menggenggam terlalu erat bisa membuat hidup menyempit.', 'Genggaman mulai longgar: kamu belajar berbagi atau melepas, atau justru terlalu boros. Cari keseimbangan antara menjaga dan mengalirkan.', 'Seorang pria bermahkota dan berjubah duduk di bangku sambil memeluk sebuah koin di dada, satu di kepala, dan menginjak dua di kakinya. Kota berdiri di belakangnya di bawah langit kelabu — lambang penjagaan dan keterikatan pada milik.', 'Jaga yang penting, tetapi tanyakan apakah ada yang bisa kamu bagi atau lepas agar hidup lebih longgar.', 'Periksa kebiasaan boros atau pelit, dan temukan titik tengah yang sehat.', 0, 0),
  ('five-of-pentacles', 'Five of Pentacles', 5, 'minor', 'pentacles', 68, '/cards/five-of-pentacles.svg', array['kesulitan', 'kekurangan', 'merasa terasing', 'ketidakpastian', 'bantuan di dekat']::text[], array['pemulihan', 'menerima bantuan', 'harapan', 'keluar dari kesulitan', 'keterasingan memudar']::text[], 'Dua sosok miskin berjalan dalam salju melewati jendela gereja yang bercahaya. Masa sulit dan rasa terasing nyata, tetapi bantuan ada di dekat sana jika kamu berani mengetuk.', 'Masa sulit mulai mereda, atau kamu mulai menerima bantuan. Bangkit perlahan dengan dukungan jauh lebih mungkin daripada melakukannya sendirian.', 'Seorang pria berpincang dengan tongkat dan seorang perempuan berselubung berjalan di salju malam, melewati jendela kaca patri bercahaya dengan lima koin berpentagram. Mereka tampak kedinginan dan menunduk — lambang kesulitan dan bantuan di dekat.', 'Jangan menanggung sendirian; tanyakan atau terima bantuan dari tempat yang aman.', 'Teruskan langkah pemulihan kecil dan pertahankan dukungan yang sudah kamu temukan.', -1, 1),
  ('six-of-pentacles', 'Six of Pentacles', 6, 'minor', 'pentacles', 69, '/cards/six-of-pentacles.svg', array['kemurahan hati', 'berbagi', 'timbal balik', 'keadilan', 'dukungan']::text[], array['utang budi', 'ketimpangan', 'pamrih', 'bantuan bersyarat', 'tidak adil']::text[], 'Seorang pedagang menimbang dan membagikan koin kepada dua pengemis yang berlutut. Kartu ini tentang memberi dan menerima dengan adil, kemurahan hati yang tulus, dan aliran sumber daya yang sehat.', 'Pemberian disertai pamrih, atau ada ketimpangan antara yang memberi dan menerima. Periksa apakah bantuan membebaskan atau mengikat.', 'Seorang pedagang berjubah merah membawa timbangan di satu tangan dan membagikan koin ke tangan seorang pengemis berlutut. Seorang pengemis lain menunggu di sisinya dengan tangan terbuka, dan enam koin melayang di atas mereka — lambang pembagian dan keseimbangan.', 'Berbagilah dengan tulus sesuai kemampuanmu, dan terima bantuan tanpa rasa malu berlebihan.', 'Jelaskan syarat bantuan secara terbuka agar tidak ada yang merasa berutang diam-diam.', 1, -1),
  ('seven-of-pentacles', 'Seven of Pentacles', 7, 'minor', 'pentacles', 70, '/cards/seven-of-pentacles.svg', array['kesabaran', 'evaluasi', 'investasi waktu', 'panen belum tiba', 'penilaian']::text[], array['tidak sabar', 'usaha sia-sia', 'hasil minim', 'menyerah', 'kurang arah']::text[], 'Sosok bertumpu pada cangkulnya menatap tanaman yang tumbuh dengan koin. Kamu sudah menanam; kini saatnya menilai sambil bersabar. Hasil butuh waktu, dan evaluasi membantu menjaga arah.', 'Tidak sabar karena hasil tampak lambat, atau merasa usaha sia-sia. Tinjau strategi tanpa menyalahkan diri; mungkin waktunya penyesuaian, bukan menyerah.', 'Seorang petani bertumpu pada cangkul sambil memandang semak hijau yang berbuah tujuh koin emas. Ladang hijau membentang di belakangnya di bawah langit kuning — lambang kesabaran dan hasil yang sedang tumbuh.', 'Evaluasi usahamu dengan jujur, lalu lanjutkan dengan sabar pada hal yang terbukti tumbuh.', 'Tinjau apakah strategimu perlu disesuaikan, dan pecah target menjadi tonggak kecil yang terlihat.', 1, -1),
  ('eight-of-pentacles', 'Eight of Pentacles', 8, 'minor', 'pentacles', 71, '/cards/eight-of-pentacles.svg', array['ketekunan', 'penguasaan keterampilan', 'dedikasi', 'latihan', 'kerja teliti']::text[], array['perfeksionisme', 'kerja monoton', 'kurang motivasi', 'jalan pintas', 'kualitas turun']::text[], 'Pengrajin menatah koin demi koin dengan tekun di bengkelnya. Keahlian tumbuh lewat latihan, fokus, dan kerja yang diulang dengan perhatian. Nikmati proses menjadi lebih baik.', 'Kerja menjadi monoton, terlalu perfeksionis, atau kamu mengambil jalan pintas. Periksa apakah kamu masih peduli pada hasilnya.', 'Seorang pengrajin berapron duduk di bangku bengkel, memahat koin berpentagram dengan palu dan pahat. Beberapa koin sudah tergantung di dinding dan satu tergeletak di tanah, dengan kota kecil di kejauhan — lambang ketekunan dan penguasaan.', 'Latih satu keterampilan secara rutin dan hargai kemajuan kecil yang terlihat.', 'Seimbangkan standar dengan keselesaian: kerjakan dengan baik, tetapi selesaikan dan lanjutkan.', 1, -1),
  ('nine-of-pentacles', 'Nine of Pentacles', 9, 'minor', 'pentacles', 72, '/cards/nine-of-pentacles.svg', array['kemandirian', 'kemewahan', 'hasil kerja keras', 'ketenangan', 'penghargaan diri']::text[], array['ketergantungan', 'pamer', 'kerja berlebih', 'kesepian', 'rasa tidak cukup']::text[], 'Seorang perempuan berdiri anggun di kebunnya dengan elang di tangan, dikelilingi buah anggur. Hasil jerih payahmu menghadirkan kemandirian, kenyamanan, dan kemampuan menikmati hidup dengan caramu.', 'Kemandirian terasa sepi atau kamu terlalu menekankan citra dan kemewahan. Bisa juga kamu masih bergantung pada orang lain. Periksa apakah kenyamananmu terasa utuh.', 'Seorang perempuan berbusana bersulam emas berdiri di kebun anggur dengan elang bertudung di tangan kirinya. Sembilan koin tergantung di antara anggur dan keong merayap di dekatnya, dengan kastil jauh di belakang — lambang kemandirian dan hasil jerih payah.', 'Nikmati apa yang sudah kamu bangun dengan tenang, dan rawat kemandirianmu dengan bijak.', 'Periksa apakah kamu terlalu bergantung atau terlalu menutup diri, lalu cari keseimbangan.', 2, 0),
  ('ten-of-pentacles', 'Ten of Pentacles', 10, 'minor', 'pentacles', 73, '/cards/ten-of-pentacles.svg', array['warisan', 'stabilitas keluarga', 'kemakmuran jangka panjang', 'tradisi', 'fondasi kokoh']::text[], array['konflik warisan', 'ketidakstabilan', 'beban keluarga', 'investasi berisiko', 'ikatan renggang']::text[], 'Tiga generasi berkumpul di gerbang rumah besar dengan sepuluh koin tersusun di atasnya. Kartu ini melambangkan kemakmuran yang bertahan lama, keluarga, dan fondasi yang diwariskan.', 'Fondasi terasa rapuh: perbedaan soal warisan, tekanan keluarga, atau keputusan finansial berisiko. Perjelas kesepakatan dan lindungi apa yang penting.', 'Seorang lelaki tua berjubah bersulam duduk di bawah lengkung gerbang bersama pasangan muda, seorang anak, dan dua anjing. Sepuluh koin tersusun di atas mereka dengan rumah-rumah batu dan kota di belakang — lambang warisan dan kemakmuran jangka panjang.', 'Bangun dan jaga sesuatu yang bisa bertahan, dan hargai orang-orang yang menjadi bagian dari fondasimu.', 'Rembukkan kesepakatan keluarga dan keuangan dengan terbuka agar fondasinya tidak retak.', 2, -1),
  ('page-of-pentacles', 'Page of Pentacles', 11, 'minor', 'pentacles', 74, '/cards/page-of-pentacles.svg', array['belajar', 'ketekunan pemula', 'rencana praktis', 'peluang studi', 'kesungguhan']::text[], array['menunda', 'kurang fokus', 'tidak praktis', 'malas', 'rencana tidak terwujud']::text[], 'Pemuda menatap koin di tangannya sambil berdiri di ladang yang subur. Sosok atau sikap ini tekun, penuh rasa ingin tahu praktis, dan siap belajar langkah demi langkah menuju tujuan nyata.', 'Rencana tidak terwujud karena menunda, kurang fokus, atau terlalu mengawang. Kembali ke langkah kecil yang konkret.', 'Seorang pemuda bertopi hijau dan berjubah bermotif bunga berdiri di ladang yang dibajak, menatap koin berpentagram yang ia angkat dengan hati-hati. Pegunungan dan pepohonan menghiasi latar di bawah langit kuning — lambang kesungguhan belajar.', 'Pelajari satu keterampilan praktis dengan konsisten, sedikit demi sedikit setiap hari.', 'Ubah rencana besar menjadi daftar langkah kecil yang bisa kamu mulai minggu ini.', 1, -1),
  ('knight-of-pentacles', 'Knight of Pentacles', 12, 'minor', 'pentacles', 75, '/cards/knight-of-pentacles.svg', array['ketekunan', 'dapat diandalkan', 'kerja metodis', 'kesabaran', 'tanggung jawab']::text[], array['stagnan', 'terlalu kaku', 'membosankan', 'perfeksionis', 'lambat']::text[], 'Kesatria berkuda di ladang membawa koin dengan langkah tenang. Sosok atau sikap ini setia, metodis, dan dapat diandalkan; pelan namun pasti, ia menyelesaikan apa yang ia mulai.', 'Ketekunan berubah menjadi stagnan, kaku, atau terjebak rutinitas. Kehati-hatian berlebihan membuat kemajuan sangat lambat.', 'Seorang kesatria berzirah gelap menunggang kuda hitam yang berdiri tenang di ladang yang dibajak. Ia memandangi koin berpentagram di tangannya, dengan helm berhias daun dan langit kuning di atas — lambang ketekunan dan kesetiaan.', 'Teruskan langkah teratur dan konsisten; kemajuan yang stabil akan menumpuk.', 'Selipkan sedikit fleksibilitas ke dalam rutinitas agar tidak terjebak kebiasaan lama.', 1, -1),
  ('queen-of-pentacles', 'Queen of Pentacles', 13, 'minor', 'pentacles', 76, '/cards/queen-of-pentacles.svg', array['kehangatan praktis', 'merawat', 'kelimpahan', 'rumah tangga', 'bijak mengelola']::text[], array['terlalu mengurus', 'mengabaikan diri', 'materialistis', 'cemas soal cukup', 'terbebani']::text[], 'Ratu duduk di taman subur memeluk koin seperti sesuatu yang berharga. Sosok atau sikap ini hangat, praktis, dan pandai merawat: rumah, orang, dan sumber daya dengan bijak.', 'Kepedulian bisa menjadi beban, atau kekhawatiran akan kecukupan membuatmu terlalu sibuk mengatur. Ingat merawat dirimu sendiri.', 'Seorang ratu bermahkota duduk di singgasana yang dihiasi buah dan bunga, memeluk koin besar di pangkuannya. Kelinci berlari di kakinya dan taman rimbun dengan pegunungan tampak di belakang — lambang perawatan dan kelimpahan.', 'Rawat orang dan hal-hal yang kamu cintai dengan cara praktis, dan jangan lupa merawat dirimu.', 'Kurangi tuntutan untuk mengurus semuanya; sisihkan waktu istirahat dan minta bantuan.', 2, -1),
  ('king-of-pentacles', 'King of Pentacles', 14, 'minor', 'pentacles', 77, '/cards/king-of-pentacles.svg', array['kemakmuran', 'stabilitas', 'keandalan', 'kepemimpinan praktis', 'keamanan']::text[], array['materialistis', 'kaku', 'serakah', 'terlalu mengontrol', 'berorientasi status']::text[], 'Raja duduk di singgasana yang dihiasi anggur dan banteng, dikelilingi kekayaan yang ia bangun sendiri. Sosok atau sikap ini matang, dapat diandalkan, dan memimpin dengan menjaga keamanan orang lain.', 'Orientasi pada kekayaan atau status membuat sikap kaku, serakah, atau mengontrol. Kemakmuran sejati juga mencakup rasa cukup dan kemurahan hati.', 'Seorang raja bermahkota duduk di singgasana berukir banteng dengan jubah bermotif anggur, memegang koin dan tongkat kerajaan. Ia dikelilingi taman rimbun dan kastil kokoh di belakangnya — lambang kemakmuran yang dibangun dengan kerja dan kesabaran.', 'Bangun keamanan dengan langkah konsisten, dan gunakan kemakmuranmu untuk menopang orang lain.', 'Tanyakan apakah ambisi materi sudah cukup dan apakah kamu masih terbuka untuk berbagi.', 2, -1)
