-- Seed 1/3: tarot_categories, tarot_cards, tarot_card_categories (dihasilkan oleh scripts/build-data.mjs)
begin;

on conflict (id) do update set label = excluded.label, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order;

on conflict (id) do update set name = excluded.name, card_number = excluded.card_number, arcana = excluded.arcana, suit = excluded.suit, sort_order = excluded.sort_order, image_path = excluded.image_path, keywords_upright = excluded.keywords_upright, keywords_reversed = excluded.keywords_reversed, meaning_upright = excluded.meaning_upright, meaning_reversed = excluded.meaning_reversed, description = excluded.description, guidance_upright = excluded.guidance_upright, guidance_reversed = excluded.guidance_reversed, tone_upright = excluded.tone_upright, tone_reversed = excluded.tone_reversed;

on conflict (card_id, category_id) do update set weight = excluded.weight;

commit;
